var UNITS = [{"n": 1, "title": "Como ler o bloco e o art. 544 (vigência)", "cvar": "u1", "lessons": [{"id": "K1", "type": "teoria", "title": "Mapa dos artigos e datas de efeitos", "xp": 10, "data": "V1"}, {"id": "K2", "type": "drill", "title": "Praticar · vigência e estrutura", "xp": 25, "data": ["S1", "S2", "S3", "S4", "T0", "T1", "T2", "T3"]}, {"id": "K3", "type": "flash", "title": "Flashcards · vigência (art. 544)", "xp": 15, "data": [0, 1, 2, 3, 4, 5, 6]}]}, {"n": 2, "title": "CTN, importação, incorporação e FAT (arts. 496 a 500)", "cvar": "u2", "lessons": [{"id": "K4", "type": "teoria", "title": "Imunidade religiosa, declaração de importação, patrimônio de afetação e FAT", "xp": 10, "data": "V2"}, {"id": "K5", "type": "drill", "title": "Praticar · arts. 496 a 500", "xp": 25, "data": ["S5", "S6", "S7", "S8", "T4", "T5", "T6", "T7"]}, {"id": "K6", "type": "flash", "title": "Flashcards · arts. 496 a 500", "xp": 15, "data": [7, 8, 9, 10, 11, 12, 13]}]}, {"n": 3, "title": "IRPJ, CSLL e retenções na fonte (arts. 502 a 507, 509, 512 a 515, 526, 533 a 535)", "cvar": "u3", "lessons": [{"id": "K7", "type": "teoria", "title": "Retenção na fonte, variação cambial, mercados futuros e benefícios", "xp": 10, "data": "V3"}, {"id": "K8", "type": "drill", "title": "Praticar · IR e CSLL", "xp": 25, "data": ["S9", "S10", "S11", "S12", "T8", "T9", "T10", "T11"]}, {"id": "K9", "type": "flash", "title": "Flashcards · IR e CSLL", "xp": 15, "data": [14, 15, 16, 17, 18, 19, 20, 21, 22]}]}, {"n": 4, "title": "Redução das alíquotas de ICMS e ISS, 2029 a 2032 (arts. 501 e 508)", "cvar": "u4", "lessons": [{"id": "K10", "type": "teoria", "title": "Art. 31-A da LC 87 e art. 8º-B da LC 116", "xp": 10, "data": "V4"}, {"id": "K11", "type": "drill", "title": "Praticar · redução gradual", "xp": 25, "data": ["S13", "S14", "S15", "S16", "S17", "T12", "T13", "T14", "T15", "T16"]}, {"id": "K12", "type": "flash", "title": "Flashcards · ICMS e ISS na transição", "xp": 15, "data": [23, 24, 25, 26, 27, 28, 29, 30]}]}, {"n": 5, "title": "IPI, importação e regimes especiais (arts. 497, 509, 511, 515, 521 a 532)", "cvar": "u5", "lessons": [{"id": "K13", "type": "teoria", "title": "Suspensões, isenções e quem é contribuinte ou responsável do IPI", "xp": 10, "data": "V5"}, {"id": "K14", "type": "drill", "title": "Praticar · IPI e regimes", "xp": 25, "data": ["S18", "S19", "S20", "S21", "T17", "T18", "T19", "T20"]}, {"id": "K15", "type": "flash", "title": "Flashcards · IPI e regimes especiais", "xp": 15, "data": [31, 32, 33, 34, 35, 36, 37, 38, 39]}]}, {"n": 6, "title": "Etanol e revogações (arts. 536 a 543)", "cvar": "u1", "lessons": [{"id": "K16", "type": "teoria", "title": "PIS/Cofins do etanol; revogações de 2025, 2027 e 2033", "xp": 10, "data": "V6"}, {"id": "K17", "type": "drill", "title": "Praticar · etanol e revogações", "xp": 25, "data": ["S22", "S23", "S24", "S25", "S26", "T21", "T22", "T23", "T24", "T25"]}, {"id": "K18", "type": "flash", "title": "Flashcards · etanol e revogações", "xp": 15, "data": [40, 41, 42, 43, 44, 45, 46, 47, 48]}]}, {"n": 7, "title": "Fixação", "cvar": "u1", "lessons": [{"id": "Krev", "type": "review", "title": "Revisão geral do módulo", "xp": 60, "data": null}, {"id": "K19", "type": "missao", "title": "Missão TEC Concursos", "xp": 15, "data": null}, {"id": "K20", "type": "prova", "title": "Simulado cronometrado", "xp": 100, "data": null}]}];
var COM = {"0": "<p>Errado. A lei vigora na publicação, mas os efeitos são escalonados (2025, 2026, 2027, 2029, 2033 e o 4º mês subsequente).</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "1": "<p>Certo. Art. 544, VI: “demais dispositivos”.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "2": "<p>Errado. O art. 501 não consta nos incisos II a V; produz efeitos em 2026 (inciso VI). A redução é que ocorre em 2029-2032.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "3": "<p>Certo. Art. 544, V.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "4": "<p>Errado. O art. 3º da Lei 10.931 (art. 498) afasta a responsabilidade do terreno e das acessões, salvo tributos calculados sobre as receitas da própria incorporação.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "5": "<p>Certo. Lei 10.931, art. 4º, §§ 6º e 8º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "6": "<p>Errado. Inverteu os números: 18% da CBS vão ao FAT; pelo menos 28% dessa arrecadação são repassados ao BNDES.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "7": "<p>Certo. Art. 44, parágrafo único, do DL 37/1966.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "8": "<p>Certo. Art. 31 da Lei 10.833, na redação do art. 509.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "9": "<p>Certo. Art. 2º, IV, “a”, da LC 101: exclusão, na União, dos valores transferidos, inclusive os do Fundo do art. 159-A.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "10": "<p>Errado. Ambos constam do inciso III do art. 544: 1º/1/2027.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "11": "<p>Errado. O art. 17 da Lei 14.789 diz o contrário: a lei não impede a fruição desses incentivos, inclusive ZFM, Sudene e Sudam.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "12": "<p>Certo. Art. 31-A, caput e incisos I a IV, da LC 87.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "13": "<p>Errado. Ele consta dos “demais dispositivos”: efeitos desde 2026 (art. 544, VI).</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "14": "<p>Certo. § 2º do art. 31-A (LC 87) e § 1º do art. 8º-B (LC 116).</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "15": "<p>Certo. 5% x (1 - 0,40) = 3%.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "16": "<p>Errado. O § 6º fala em maioria simples dos votos.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "17": "<p>Certo. Lei 10.833, art. 67, caput e § 3º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "18": "<p>Errado. O art. 11, § 1º, da Lei 11.196 fala em conversão em isenção.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "19": "<p>Errado. Inciso III do art. 544: 1º/1/2027.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "20": "<p>Certo. Art. 11, § 1º, II, da Lei 11.196.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "21": "<p>Certo. Art. 543, I, III e IV.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "22": "<p>Errado. Os arts. 1º a 5º-A, 7º, 8º, 10 a 12, 32 e 47 são revogados em 1º/1/2027 (art. 542, XVIII).</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "23": "<p>Errado. Art. 544, I: primeiro dia do quarto mês subsequente à publicação.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "24": "<p>Certo. § 4º-C do art. 5º da Lei 9.718, art. 537.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "25": "<p>Certo. Art. 541 e art. 544, II.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>"};
